    [ "$status" -eq 0 ]
    [ "$(echo "$output" | jq -r '.secrets[] | select(.name=="edge-warn14") | .days_until_expiry')" = "14" ]
    [ "$(echo "$output" | jq -r '.secrets[] | select(.name=="edge-warn14") | .status')" = "warning" ]
